pub fn apply_budget(
    ranked: Vec<RankedBlock>,
    total_before: usize,
    budget: &Budget,
    row_texts: &[String],
    diagnostics: Vec<Diagnostic>,
) -> SearchResponse {
    let mut kept = Vec::new();
    let mut total_tokens = 0usize;
    debug_assert_eq!(ranked.len(), row_texts.len(), "each block needs its printed row");
